theory.code:
const user = {
  id: 1,
  name: "Anna Nowak",
  age: 28,
  address: { city: "Krakow", zip: "30-001" },
  greet() {
    return `Hej, jestem ${this.name}!`;
  },
};

console.log(user.name);              // "Anna Nowak"
console.log(user["address"]["city"]); // "Krakow"
console.log(user.greet());           // "Hej, jestem Anna Nowak!"

// Dynamiczny klucz
const field = "name";
console.log(user[field]); // "Anna Nowak" - user['name'] przez zmienna

// Computed property PRZY tworzeniu obiektu
const prefix = "user";
const dynamic = {
  [`${prefix}Name`]: "Jan", // klucz OBLICZONY jako 'userName'
};
console.log(dynamic.userName); // "Jan"

// Shorthand properties
const name = "Basia";
const age = 22;
const person = { name, age }; // zamiast { name: name, age: age }
console.log(person); // { name: 'Basia', age: 22 }

const user = { name: "Anna" };
const field = "name";

console.log(user.field); // BLEDNIE: undefined - szuka DOSLOWNEGO klucza 'field'

const user = { name: "Anna" };
const field = "name";

console.log(user[field]); // POPRAWNIE: "Anna" - user['name']

